import { useMemo, useState } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { calculateClubAverage } from '../utils/ratingUtils';
import FilmList from '../components/films/FilmList';
import PopcornRating from '../components/common/PopcornRating';
import CreditsModal from '../components/common/CreditsModal';
import TrailerModal from '../components/common/TrailerModal';
import {
    countValidRatings,
    formatCurrency,
    formatDayGap,
    formatRuntime,
    getFilmBackdrop,
    getFilmBackdrops,
    isUpcomingHolidayPod,
    parseGenres,
    parseWatchDate,
} from '../utils/filmUtils';
import { getPersonProfileByName } from '../utils/personUtils';
import { Film } from '../types/film';
import { getMemberImage } from '../types/team';
import FilmCastStrip from '../components/films/FilmCastStrip';
import FilmStills from '../components/films/FilmStills';
import PlotParagraphs from '../components/films/PlotParagraphs';
import ScoreQualifierNote from '../components/films/ScoreQualifierNote';
import SelectorPickBadge from '../components/films/SelectorPickBadge';
import {
    PopcornPodStamp,
    PopcornPodDisclaimer,
    POPCORN_POD_POSTER_FILTER,
} from '../components/films/PopcornPod';
import {
    HolidayPodStamp,
    HolidayPodDisclaimer,
    getHolidayTheme,
} from '../components/films/HolidayPod';
import PersonStrip, { PersonStripEntry } from '../components/films/PersonStrip';
import PageLayout from '../components/layout/PageLayout';
import BaseCard from '../components/common/BaseCard';
import AccentCard from '../components/common/AccentCard';
import Button from '../components/common/Button';
import QuoteMarkIcon from '../components/common/QuoteMarkIcon';
import CollapsibleContent from '../components/common/CollapsableContent';
import LoadingSpinner from '../components/common/LoadingSpinner';
import ErrorDisplay from '../components/common/ErrorDisplay';
import { useFilmDetails } from '../hooks/useFilmDetails';
import { useFilmOverrides } from '../hooks/useFilmOverrides';
import { useFilmTrophies } from '../hooks/useFilmTrophies';
import MyRatingEditor from '../components/films/MyRatingEditor';
import FilmTrophyEditor from '../components/films/FilmTrophyEditor';
import FilmDetailsEditor from '../components/films/FilmDetailsEditor';
import TrophyGallery from '../components/common/TrophyGallery';
import { resolveFilmTrophies } from '../utils/trophyUtils';
import WatchTimelineNav from '../components/common/WatchTimelineNav';
import LogResponses from '../components/responses/LogResponses';
import { clubThreadId } from '../types/responses';
import SelectionCommitteeBackground from '../components/common/SelectionCommitteeBackground';
import { CalendarDaysIcon, ChevronLeftIcon } from '@heroicons/react/24/outline';

// Small-caps field label, the profile's stat-card label treatment.
const FIELD_LABEL = 'text-[11px] font-medium uppercase tracking-[0.14em] text-slate-400';

// Crew fields shown as headshot cards in the "Crew" strip, with their display
// role. Actors are intentionally excluded — they're covered by the cast strip.
const CREW_STRIP_FIELDS: { field: keyof Film; label: string }[] = [
    { field: 'director', label: 'Director' },
    { field: 'writer', label: 'Writer' },
    { field: 'cinematographer', label: 'Cinematography' },
    { field: 'editor', label: 'Editor' },
    { field: 'productionDesigner', label: 'Production Design' },
    { field: 'musicComposer', label: 'Music' },
    { field: 'costumeDesigner', label: 'Costume Design' },
];

// Shortens OMDb's verbose rating source names for the rating chips.
const RATING_SOURCE_LABELS: Record<string, string> = {
    'Internet Movie Database': 'IMDb',
    'Rotten Tomatoes': 'Rotten Tomatoes',
    Metacritic: 'Metacritic',
};

const FilmDetailPage = () => {
    const { imdbId } = useParams<{ imdbId: string }>();
    const navigate = useNavigate();
    const [isTrailerOpen, setIsTrailerOpen] = useState(false);

    const {
        film,
        loading,
        error,
        filmsBySameSelector,
        previousFilm,
        nextFilm,
        nextSelectorPlaceholder,
        watchUrl,
        linkCheckStatus,
        creditsModalState,
        handleCreditPersonClick,
        closeCreditsModal,
        personAllFilmographies,
    } = useFilmDetails(imdbId);

    // Member edits to this film's ratings, read live from `main` while signed
    // in. Empty for everyone else, which is what keeps the markers below an
    // editing affordance rather than something a visitor sees.
    const overrides = useFilmOverrides(imdbId);
    // The club's awards for this film. Unlike the overrides above these are page
    // content rather than an editing affordance, so they resolve for everyone —
    // from the bundle for a visitor, from `main` for a signed-in member.
    const trophies = useFilmTrophies(imdbId);

    const capitalizeFirstLetter = (str: string): string =>
        str ? str.charAt(0).toUpperCase() + str.slice(1) : str;

    // Build the "Crew" strip: one card per person, grouping a person's roles
    // (e.g. someone who both directed and wrote) into a single subtitle, and
    // resolving their TMDb headshot via personProfiles.
    const crewPeople = useMemo<PersonStripEntry[]>(() => {
        if (!film) return [];
        const order: string[] = [];
        const byKey = new Map<string, { name: string; roles: string[] }>();
        CREW_STRIP_FIELDS.forEach(({ field, label }) => {
            const value = film[field];
            if (!value || typeof value !== 'string' || value.toLowerCase() === 'n/a') return;
            value
                .split(',')
                .map((n) => n.trim())
                .filter(Boolean)
                .forEach((name) => {
                    const key = name.toLowerCase();
                    let entry = byKey.get(key);
                    if (!entry) {
                        entry = { name, roles: [] };
                        byKey.set(key, entry);
                        order.push(key);
                    }
                    if (!entry.roles.includes(label)) entry.roles.push(label);
                });
        });
        return order.map((key) => {
            const { name, roles } = byKey.get(key)!;
            return {
                name,
                subtitle: roles.join(' · '),
                profileUrl: getPersonProfileByName(name)?.profileUrl ?? null,
                credits: personAllFilmographies[name] ?? [],
            };
        });
    }, [film, personAllFilmographies]);

    // The shelf as it renders: the sheet's `trophyNotes` prose parsed into
    // awards, then the ones members have handed out on the site.
    const filmTrophies = useMemo(
        () => (film ? resolveFilmTrophies(film, trophies.trophies) : []),
        [film, trophies.trophies]
    );

    // UI Helper function (can remain in component or be moved to utils if more broadly used)
    if (loading) {
        return <LoadingSpinner />;
    }
    if (error || !film) {
        return (
            <ErrorDisplay
                message={error || 'Could not load film details.'}
                backPath="/films"
                backButtonLabel="Back to Films List"
            />
        );
    }

    const filmGenres = parseGenres(film.genre);
    const runtimeDisplay = formatRuntime(film.runtime);
    const numberOfValidRatings = countValidRatings(film.movieClubInfo?.clubRatings);
    const clubAverageDisplay =
        numberOfValidRatings >= 2 ? calculateClubAverage(film.movieClubInfo?.clubRatings) : null;
    const selectorName = film.movieClubInfo?.selector;
    const externalRatings = (film.ratings ?? []).filter(
        (r) => r.value && r.value.toLowerCase() !== 'n/a'
    );
    const boxOfficeDisplay =
        film.boxOffice && film.boxOffice.toLowerCase() !== 'n/a'
            ? film.boxOffice
            : formatCurrency(film.revenue);
    const budgetDisplay = formatCurrency(film.budget);
    const awardsDisplay = film.awards && film.awards.toLowerCase() !== 'n/a' ? film.awards : null;
    const directorCredit =
        film.director && film.director.toLowerCase() !== 'n/a'
            ? film.director
                  .split(',')
                  .map((name) => name.trim())
                  .filter(Boolean)
                  .join(' & ')
            : null;
    // Backdrop for the details strip (genres/budget/awards). Prefer a second
    // image so it differs from the right-anchored header backdrop; fall back to
    // the primary backdrop when only one is available.
    const filmBackdrops = getFilmBackdrops(film);
    const detailsBackdrop = filmBackdrops[1] ?? filmBackdrops[0];
    // Gallery of "stills": every backdrop plus the cover/poster, de-duplicated.
    const stillImages = [...filmBackdrops, film.poster].filter(
        (url, i, arr): url is string => !!url && arr.indexOf(url) === i
    );
    const MAX_RATING = 9;
    const holidayTheme = getHolidayTheme(film.holidayPod);
    const isUpcomingPod = isUpcomingHolidayPod(film);
    const canWatch = linkCheckStatus === 'valid' && !!watchUrl;

    // Time elapsed between this screening and the club's adjacent screenings.
    const watchDateObj = parseWatchDate(film.movieClubInfo?.watchDate);
    const prevWatchDateObj = parseWatchDate(previousFilm?.movieClubInfo?.watchDate);
    const nextWatchDateObj = parseWatchDate(nextFilm?.movieClubInfo?.watchDate);
    // Where this film falls among its picker's screenings — one plus the
    // dated picks of theirs that came before it. Undated means not watched yet.
    const selectorPickNumber = watchDateObj
        ? filmsBySameSelector.filter((other) => {
              const otherDate = parseWatchDate(other.movieClubInfo?.watchDate);
              return otherDate !== null && otherDate < watchDateObj;
          }).length + 1
        : null;
    const MS_PER_DAY = 1000 * 60 * 60 * 24;
    const sincePreviousGap =
        watchDateObj && prevWatchDateObj
            ? formatDayGap(
                  Math.round((watchDateObj.getTime() - prevWatchDateObj.getTime()) / MS_PER_DAY)
              )
            : null;
    const untilNextGap =
        watchDateObj && nextWatchDateObj
            ? formatDayGap(
                  Math.round((nextWatchDateObj.getTime() - watchDateObj.getTime()) / MS_PER_DAY)
              )
            : null;

    return (
        <PageLayout>
            {/* Always mounted so the modal can run its own close animation. */}
            <CreditsModal
                isOpen={creditsModalState.isOpen}
                onClose={closeCreditsModal}
                personName={creditsModalState.personName}
                filmography={creditsModalState.filmography}
                currentFilmId={film.imdbID}
            />

            {film.trailerKey && (
                <TrailerModal
                    isOpen={isTrailerOpen}
                    onClose={() => setIsTrailerOpen(false)}
                    trailerKey={film.trailerKey}
                    title={film.title}
                />
            )}

            <div className="">
                <Button
                    onClick={() => navigate(-1)}
                    variant="link"
                    size="md"
                    className="mb-8 group"
                >
                    <ChevronLeftIcon
                        className="h-5 w-5 transition-transform group-hover:-translate-x-1"
                        aria-hidden="true"
                    />
                    Back
                </Button>

                <BaseCard key={`film-card-${film.imdbID}`} className="!p-0 overflow-hidden mb-12 ">
                    <div className="md:flex">
                        <div className="md:flex-shrink-0 md:w-1/3 lg:w-[400px] relative group overflow-hidden">
                            <img
                                src={film.poster}
                                alt={`${film.title} poster`}
                                className={`h-full w-full object-cover ${film.popcornPod ? POPCORN_POD_POSTER_FILTER : ''} ${holidayTheme?.posterFilter ?? ''}`}
                                onError={(e) => {
                                    const target = e.target as HTMLImageElement;
                                    target.src = '/placeholder-poster.png';
                                    target.onerror = null;
                                }}
                            />
                            {/* Not a selection: deface the poster instead of offering a Watch link. */}
                            {film.popcornPod && <PopcornPodStamp />}
                            {film.holidayPod && <HolidayPodStamp holiday={film.holidayPod} />}
                            {canWatch && (
                                <a
                                    href={watchUrl!}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="absolute inset-0 pointer-events-none md:group-hover:pointer-events-auto"
                                    aria-label={`Watch ${film.title}`}
                                >
                                    <div
                                        className={`absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/80 to-transparent flex items-end justify-end p-4 transition-opacity duration-300 ease-in-out h-auto md:h-1/3 opacity-100 md:opacity-0 md:group-hover:opacity-100`}
                                    >
                                        <span
                                            className={`bg-gray-900 bg-opacity-70 opacity-70 text-gray-100 text-lg font-semibold pr-5 pl-3 py-2 rounded-lg inline-flex items-center shadow-xl border border-white/20 pointer-events-auto `}
                                        >
                                            <svg
                                                xmlns="http://www.w3.org/2000/svg"
                                                className="h-6 w-6 mr-2.5"
                                                viewBox="0 0 20 20"
                                                fill="currentColor"
                                            >
                                                <path
                                                    fillRule="evenodd"
                                                    d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z"
                                                    clipRule="evenodd"
                                                />
                                            </svg>
                                            Watch
                                        </span>
                                    </div>
                                </a>
                            )}
                        </div>

                        <div className="relative p-6 md:p-8 flex-grow overflow-hidden">
                            {getFilmBackdrop(film) && (
                                <SelectionCommitteeBackground
                                    imageUrl={getFilmBackdrop(film)}
                                    className="!rounded-none"
                                    scale={1}
                                    opacity={0.14}
                                    align="right"
                                />
                            )}
                            <div className="relative z-10">
                                {/* Set like a title card, as the profile banner is:
                                    the year and director as a small-caps credit
                                    over the title, a short rule, then the tagline
                                    as an epigraph in serif italic. */}
                                {(film.year || directorCredit) && (
                                    <p className="mb-3 text-[11px] font-medium uppercase tracking-[0.2em] text-blue-300/80">
                                        {film.year}
                                        {film.year && directorCredit && (
                                            <span
                                                className="mx-2 text-slate-500"
                                                aria-hidden="true"
                                            >
                                                ·
                                            </span>
                                        )}
                                        {directorCredit && <>Directed by {directorCredit}</>}
                                    </p>
                                )}
                                <h1 className="font-serif text-3xl lg:text-4xl leading-tight tracking-tight text-slate-100 break-words">
                                    {film.title}
                                </h1>
                                <span
                                    className="mt-4 mb-4 block h-px w-12 bg-slate-500/60"
                                    aria-hidden="true"
                                />
                                {film.tagline && (
                                    <p className="mb-5 font-serif italic leading-relaxed text-slate-300">
                                        {film.tagline}
                                    </p>
                                )}
                                {film.popcornPod && <PopcornPodDisclaimer />}
                                {film.holidayPod && (
                                    <HolidayPodDisclaimer
                                        holiday={film.holidayPod}
                                        upcoming={isUpcomingPod}
                                    />
                                )}
                                <div className="flex flex-wrap items-center gap-x-4 gap-y-2 text-[11px] font-medium uppercase tracking-[0.14em] text-slate-400 mb-5">
                                    {clubAverageDisplay && (
                                        <div
                                            className="flex items-baseline gap-1.5"
                                            title={`Average Club Rating (${numberOfValidRatings} ratings)`}
                                        >
                                            <span className="font-serif text-lg normal-case tracking-normal tabular-nums leading-none text-blue-300">
                                                {clubAverageDisplay}
                                            </span>
                                            <span className="text-slate-500">/ {MAX_RATING}</span>
                                            <span>Club Avg</span>
                                        </div>
                                    )}
                                    {runtimeDisplay && (
                                        <span
                                            className={
                                                clubAverageDisplay
                                                    ? 'border-l border-slate-600 pl-4'
                                                    : ''
                                            }
                                        >
                                            {runtimeDisplay}
                                        </span>
                                    )}
                                    {film.rated !== 'N/A' && (
                                        <span
                                            className={
                                                clubAverageDisplay || runtimeDisplay
                                                    ? 'border-l border-slate-600 pl-4'
                                                    : ''
                                            }
                                        >
                                            {film.rated}
                                        </span>
                                    )}
                                    {film.trailerKey && (
                                        <Button
                                            type="button"
                                            onClick={() => setIsTrailerOpen(true)}
                                            variant="link"
                                            size="xs"
                                            className={
                                                clubAverageDisplay ||
                                                runtimeDisplay ||
                                                film.rated !== 'N/A'
                                                    ? 'border-l border-slate-700/60 pl-4 rounded-none'
                                                    : ''
                                            }
                                        >
                                            <svg
                                                xmlns="http://www.w3.org/2000/svg"
                                                className="h-3.5 w-3.5"
                                                viewBox="0 0 20 20"
                                                fill="currentColor"
                                            >
                                                <path
                                                    fillRule="evenodd"
                                                    d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z"
                                                    clipRule="evenodd"
                                                />
                                            </svg>
                                            Trailer
                                        </Button>
                                    )}
                                </div>

                                {stillImages.length > 0 && (
                                    <div className="mb-5">
                                        <FilmStills images={stillImages} title={film.title} />
                                    </div>
                                )}

                                {externalRatings.length > 0 && (
                                    <div className="flex flex-wrap gap-2 mb-5">
                                        {externalRatings.map((rating) => {
                                            const isImdb =
                                                rating.source === 'Internet Movie Database';
                                            const imdbUrl =
                                                isImdb && film.imdbID
                                                    ? `https://www.imdb.com/title/${film.imdbID}/`
                                                    : null;
                                            const chipContent = (
                                                <>
                                                    <span className={FIELD_LABEL}>
                                                        {RATING_SOURCE_LABELS[rating.source] ??
                                                            rating.source}
                                                    </span>
                                                    <span className="font-serif tabular-nums text-slate-100">
                                                        {rating.value}
                                                    </span>
                                                </>
                                            );
                                            return imdbUrl ? (
                                                <a
                                                    key={rating.source}
                                                    href={imdbUrl}
                                                    target="_blank"
                                                    rel="noopener noreferrer"
                                                    className="group inline-flex items-baseline gap-2 px-3 py-1.5 bg-slate-700/25 hover:bg-slate-700/45 border border-yellow-500/25 hover:border-yellow-500/50 rounded-lg text-sm transition-colors duration-200"
                                                    title={`View on IMDb`}
                                                >
                                                    {chipContent}
                                                    <svg
                                                        xmlns="http://www.w3.org/2000/svg"
                                                        className="h-3 w-3 self-center text-slate-400 group-hover:text-yellow-400 transition"
                                                        viewBox="0 0 20 20"
                                                        fill="currentColor"
                                                    >
                                                        <path d="M11 3a1 1 0 100 2h2.586l-6.293 6.293a1 1 0 101.414 1.414L15 6.414V9a1 1 0 102 0V4a1 1 0 00-1-1h-5z" />
                                                        <path d="M5 5a2 2 0 00-2 2v8a2 2 0 002 2h8a2 2 0 002-2v-3a1 1 0 10-2 0v3H5V7h3a1 1 0 000-2H5z" />
                                                    </svg>
                                                </a>
                                            ) : (
                                                <span
                                                    key={rating.source}
                                                    className="inline-flex items-baseline gap-2 px-3 py-1.5 bg-slate-700/25 border border-slate-600/30 rounded-lg text-sm"
                                                    title={rating.source}
                                                >
                                                    {chipContent}
                                                </span>
                                            );
                                        })}
                                    </div>
                                )}
                                <div className="mb-5 text-slate-300 ">
                                    {/* Serif, like the interview answers on a profile. */}
                                    <CollapsibleContent
                                        buttonSize="sm"
                                        lineClamp={3}
                                        className="font-serif leading-relaxed"
                                        buttonClassName="mt-2 font-sans not-italic"
                                    >
                                        <PlotParagraphs
                                            plot={film.plot}
                                            fallback={
                                                <span className="italic text-slate-500">
                                                    Plot not available.
                                                </span>
                                            }
                                        />
                                    </CollapsibleContent>
                                </div>

                                {/* Crew & cast (director, writer, stars, ...) are shown as
                                headshot cards in the Crew/Cast strips below. */}
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-4 text-sm mb-6">
                                    {film.language && film.language.toLowerCase() !== 'n/a' && (
                                        <div>
                                            <h3 className={`${FIELD_LABEL} mb-1.5`}>Language</h3>
                                            <p className="text-slate-300">{film.language}</p>
                                        </div>
                                    )}
                                    {film.country && film.country.toLowerCase() !== 'n/a' && (
                                        <div>
                                            <h3 className={`${FIELD_LABEL} mb-1.5`}>Country</h3>
                                            <p className="text-slate-300">{film.country}</p>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>

                    {(filmGenres.length > 0 ||
                        budgetDisplay ||
                        boxOfficeDisplay ||
                        awardsDisplay ||
                        crewPeople.length > 0 ||
                        (film.cast && film.cast.length > 0)) && (
                        <div className="relative overflow-hidden">
                            {detailsBackdrop && (
                                <SelectionCommitteeBackground
                                    imageUrl={detailsBackdrop}
                                    className="!rounded-none"
                                    scale={1}
                                    opacity={0.14}
                                    align="left"
                                />
                            )}
                            <div className="relative z-10">
                                {(filmGenres.length > 0 ||
                                    budgetDisplay ||
                                    boxOfficeDisplay ||
                                    awardsDisplay) && (
                                    <div className="px-6 md:px-8 py-5 border-t border-slate-700/60 flex flex-col sm:flex-row sm:flex-wrap gap-6 sm:gap-x-10 sm:gap-y-6">
                                        {filmGenres.length > 0 && (
                                            <div className="flex-shrink-0">
                                                <h3 className={`${FIELD_LABEL} mb-2`}>Genres</h3>
                                                <div className="flex flex-wrap gap-2">
                                                    {filmGenres.map((genre) => (
                                                        <span
                                                            key={genre}
                                                            className="px-3 py-1 bg-slate-700 text-blue-300 text-xs font-medium rounded-full"
                                                        >
                                                            {genre}
                                                        </span>
                                                    ))}
                                                </div>
                                            </div>
                                        )}
                                        {budgetDisplay && (
                                            <div className="flex-shrink-0">
                                                <h3 className={`${FIELD_LABEL} mb-2`}>Budget</h3>
                                                <p className="font-serif text-lg tabular-nums text-slate-200">
                                                    {budgetDisplay}
                                                </p>
                                            </div>
                                        )}
                                        {boxOfficeDisplay && (
                                            <div className="flex-shrink-0">
                                                <h3 className={`${FIELD_LABEL} mb-2`}>
                                                    Box Office
                                                </h3>
                                                <p className="font-serif text-lg tabular-nums text-slate-200">
                                                    {boxOfficeDisplay}
                                                </p>
                                            </div>
                                        )}
                                        {awardsDisplay && (
                                            <div className="sm:flex-1 sm:basis-80">
                                                <h3 className={`${FIELD_LABEL} mb-2`}>Awards</h3>
                                                <p className="text-slate-300 leading-relaxed">
                                                    {awardsDisplay}
                                                </p>
                                            </div>
                                        )}
                                    </div>
                                )}

                                {(crewPeople.length > 0 || (film.cast && film.cast.length > 0)) && (
                                    <div className="px-6 md:px-8 pb-6 md:pb-8">
                                        {crewPeople.length > 0 && (
                                            <PersonStrip
                                                title="Crew"
                                                people={crewPeople}
                                                onPersonClick={handleCreditPersonClick}
                                            />
                                        )}
                                        {film.cast && film.cast.length > 0 && (
                                            <FilmCastStrip
                                                cast={film.cast}
                                                personAllFilmographies={personAllFilmographies}
                                                onPersonClick={handleCreditPersonClick}
                                            />
                                        )}
                                    </div>
                                )}
                            </div>
                        </div>
                    )}

                    {film.movieClubInfo && (
                        <div className="relative bg-slate-900/30 border-t-2 border-slate-700/60 p-6 md:p-8 overflow-hidden">
                            {/* Subtle ambient glow anchoring the club section */}
                            <div
                                aria-hidden="true"
                                className="pointer-events-none absolute -top-24 -right-16 h-64 w-64 rounded-full bg-blue-500/[0.07] blur-3xl"
                            />
                            <div className="relative z-10">
                                {/* Serif italic, like the profile's Interview head:
                                    this is the club's own account of the film. */}
                                <div className="mb-6 flex flex-wrap items-baseline gap-x-3 gap-y-1">
                                    <h2 className="font-serif text-2xl italic text-slate-100">
                                        Film Club Facts
                                    </h2>
                                    <span className="h-px flex-grow self-center bg-gradient-to-r from-blue-400/25 via-slate-700/60 to-transparent" />
                                </div>
                                <div className="md:flex md:justify-between md:items-start">
                                    <div className="flex-1 mb-6 md:mb-0 md:pr-6">
                                        {film.movieClubInfo.watchDate && (
                                            <div className="mb-6 inline-flex items-center gap-3 rounded-lg border border-slate-700/50 bg-slate-800/40 px-4 py-2.5">
                                                <CalendarDaysIcon className="h-5 w-5 flex-shrink-0 text-blue-400/80" />
                                                <div className="leading-tight">
                                                    <span className={`block ${FIELD_LABEL}`}>
                                                        Watch Date
                                                    </span>
                                                    <span className="mt-0.5 block font-serif text-base tabular-nums text-slate-100">
                                                        {film.movieClubInfo.watchDate}
                                                    </span>
                                                </div>
                                            </div>
                                        )}
                                        {/* An undated holiday pod isn't the up-next
                                            pick, so nothing else on the page says
                                            the club is still to meet for it. */}
                                        {isUpcomingPod && (
                                            <div className="mb-6 inline-flex items-center gap-3 rounded-lg border border-dashed border-slate-700/60 bg-slate-800/30 px-4 py-2.5">
                                                <CalendarDaysIcon className="h-5 w-5 flex-shrink-0 text-slate-500" />
                                                <div className="leading-tight">
                                                    <span className={`block ${FIELD_LABEL}`}>
                                                        Watch Date
                                                    </span>
                                                    <span
                                                        className={`mt-0.5 block font-serif text-base ${holidayTheme?.upcomingText ?? 'text-slate-300'}`}
                                                    >
                                                        Upcoming
                                                    </span>
                                                </div>
                                            </div>
                                        )}
                                        {numberOfValidRatings > 0 ? (
                                            <div>
                                                <h3 className="mb-3 text-[11px] font-medium uppercase tracking-[0.2em] text-blue-300/80">
                                                    Club Rating
                                                </h3>
                                                {clubAverageDisplay &&
                                                    !isNaN(clubAverageDisplay) && (
                                                        <div className="mb-5 flex items-center gap-x-4 gap-y-2 flex-wrap">
                                                            {/* Large serif numeral with the scale
                                                                dropped to small caps, as the
                                                                profile's stat cards set values. */}
                                                            <div className="flex items-baseline whitespace-nowrap">
                                                                <span className="font-serif text-5xl leading-none tracking-tight tabular-nums text-blue-300">
                                                                    {clubAverageDisplay}
                                                                </span>
                                                                <span className="ml-2 text-xs font-medium uppercase tracking-widest text-slate-400">
                                                                    / {MAX_RATING}
                                                                </span>
                                                            </div>
                                                            <PopcornRating
                                                                rating={clubAverageDisplay}
                                                                maxRating={MAX_RATING}
                                                                size="regular"
                                                                title={`Average rating: ${clubAverageDisplay} out of ${MAX_RATING}`}
                                                            />
                                                        </div>
                                                    )}
                                                {!clubAverageDisplay &&
                                                    numberOfValidRatings === 1 && (
                                                        <p className="mb-4 text-slate-400 text-sm italic">
                                                            Needs at least 2 ratings to show an
                                                            average.
                                                        </p>
                                                    )}
                                                <div className="mb-4 mt-4 flex items-center gap-2.5">
                                                    <h4 className={FIELD_LABEL}>
                                                        Individual Ratings
                                                    </h4>
                                                    <span
                                                        className="h-px flex-1 bg-slate-600/40"
                                                        aria-hidden="true"
                                                    />
                                                </div>
                                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-4 gap-y-4">
                                                    {film.movieClubInfo.clubRatings
                                                        .filter(
                                                            (rating) =>
                                                                rating.score !== null &&
                                                                typeof rating.score === 'number'
                                                        )
                                                        .sort((a, b) =>
                                                            a.user.localeCompare(b.user)
                                                        )
                                                        .map((rating) => {
                                                            // When any member on this film used a score qualifier (e.g. Joey's
                                                            // documentary "d"), reserve a wider fixed-width score cell for every
                                                            // row so the qualifier + info icon don't shove that row's popcorn
                                                            // out of alignment with the others.
                                                            const filmHasQualifier =
                                                                film.movieClubInfo!.clubRatings.some(
                                                                    (r) => r.scoreQualifier
                                                                );
                                                            return (
                                                                <div
                                                                    key={rating.user}
                                                                    className="space-y-2"
                                                                >
                                                                    <div className="flex items-center space-x-2">
                                                                        <Link
                                                                            to={`/profile/${encodeURIComponent(capitalizeFirstLetter(rating.user))}`}
                                                                            className="w-20 truncate text-[11px] font-medium uppercase tracking-[0.14em] text-slate-400 transition-colors hover:text-blue-300"
                                                                            title={`View ${capitalizeFirstLetter(rating.user)}'s profile`}
                                                                        >
                                                                            {capitalizeFirstLetter(
                                                                                rating.user
                                                                            )}
                                                                        </Link>
                                                                        <span
                                                                            className={`font-serif text-lg leading-none tabular-nums text-slate-100 whitespace-nowrap ${filmHasQualifier ? 'w-14' : 'w-8 text-right'}`}
                                                                        >
                                                                            {rating.score}
                                                                            {rating.scoreQualifier && (
                                                                                <ScoreQualifierNote
                                                                                    user={
                                                                                        rating.user
                                                                                    }
                                                                                    qualifier={
                                                                                        rating.scoreQualifier
                                                                                    }
                                                                                />
                                                                            )}
                                                                        </span>
                                                                        <PopcornRating
                                                                            rating={
                                                                                rating.score as number
                                                                            }
                                                                            maxRating={MAX_RATING}
                                                                            size="small"
                                                                            // Qualified scores get a distinctly deep-gold popcorn (matching
                                                                            // the amber "d") to signal that they come from a different,
                                                                            // medium-specific scoring rubric.
                                                                            className={
                                                                                rating.scoreQualifier
                                                                                    ? '[filter:sepia(1)_saturate(3.5)_hue-rotate(-18deg)_brightness(1.1)]'
                                                                                    : undefined
                                                                            }
                                                                            title={
                                                                                rating.scoreQualifier
                                                                                    ? `${capitalizeFirstLetter(rating.user)}'s ${rating.scoreQualifier === 'd' ? 'documentary' : 'qualified'} rating: ${rating.score} out of ${MAX_RATING}`
                                                                                    : `${capitalizeFirstLetter(rating.user)}'s rating: ${rating.score} out of ${MAX_RATING}`
                                                                            }
                                                                        />
                                                                        {/* Visible only to a signed-in member, since that's the
                                                                    only time the overrides are loaded. It marks a row edited
                                                                    on the site, whose spreadsheet cell is now ignored. */}
                                                                        {overrides.ratings[
                                                                            rating.user.toLowerCase()
                                                                        ] && (
                                                                            <span
                                                                                className="rounded bg-slate-700/60 px-1.5 py-0.5 text-[10px] uppercase tracking-wider text-slate-400"
                                                                                title={`Edited on the site by ${overrides.ratings[rating.user.toLowerCase()].updatedBy}. The Google Sheet no longer sets this row.`}
                                                                            >
                                                                                edited
                                                                            </span>
                                                                        )}
                                                                    </div>
                                                                    {rating.blurb && (
                                                                        // Watermarked with the reviewer's portrait — the varying subject here is the member
                                                                        <AccentCard
                                                                            accent="emerald"
                                                                            surface="inset"
                                                                            watermarkSrc={getMemberImage(
                                                                                rating.user
                                                                            )}
                                                                            className="ml-2 mt-4 px-4 pb-3 pt-3.5"
                                                                        >
                                                                            <QuoteMarkIcon className="mb-1.5 h-5 w-5 text-emerald-400/50" />
                                                                            <CollapsibleContent
                                                                                buttonSize="sm"
                                                                                lineClamp={3}
                                                                                className="text-sm italic leading-relaxed text-slate-300"
                                                                            >
                                                                                {rating.blurb}
                                                                                <span className="capitalize">
                                                                                    &nbsp;&mdash;&nbsp;
                                                                                    {capitalizeFirstLetter(
                                                                                        rating.user
                                                                                    )}
                                                                                </span>
                                                                            </CollapsibleContent>
                                                                        </AccentCard>
                                                                    )}
                                                                </div>
                                                            );
                                                        })}
                                                </div>
                                            </div>
                                        ) : (
                                            <div>
                                                {' '}
                                                <h3 className="mb-3 text-[11px] font-medium uppercase tracking-[0.2em] text-blue-300/80">
                                                    Club Rating
                                                </h3>{' '}
                                                <p className="text-slate-400 italic">
                                                    No ratings submitted yet.
                                                </p>{' '}
                                            </div>
                                        )}
                                    </div>
                                    {selectorName && (
                                        <SelectorPickBadge
                                            name={capitalizeFirstLetter(selectorName)}
                                            pickNumber={selectorPickNumber}
                                        />
                                    )}
                                </div>

                                {/* The film's own club record — whose pick, when
                                the club watched it, and its two images. Club
                                property rather than anyone's row, so any signed-in
                                member may set it; it renders nothing for a visitor. */}
                                <FilmDetailsEditor
                                    film={film}
                                    override={overrides.film}
                                    added={overrides.added}
                                    loading={overrides.loading}
                                    onSaved={(record) => overrides.applyFilmLocal(record)}
                                    onReverted={() => overrides.applyFilmLocal(null)}
                                />

                                {/* A member's own score and review, editable in place. Renders
                                nothing at all unless a member is signed in. */}
                                <MyRatingEditor
                                    film={film}
                                    ratings={overrides.ratings}
                                    overridesLoading={overrides.loading}
                                    // Keyed by the row's owner rather than by
                                    // `updatedBy`: an admin filling in the
                                    // evening's scores is the one who typed it,
                                    // not the one it belongs to.
                                    onSaved={(owner, rating) => overrides.applyLocal(owner, rating)}
                                    onReverted={(owner) => overrides.applyLocal(owner, null)}
                                />

                                {/* The club's awards for this film — the sheet's
                                `trophyNotes` prose and the ones members hand out
                                here, resolved into one shelf. The editor renders
                                nothing at all unless a member is signed in, so the
                                gallery appears for a visitor only when there is
                                something in it. */}
                                <TrophyGallery trophies={filmTrophies}>
                                    <FilmTrophyEditor
                                        film={film}
                                        trophies={trophies.trophies}
                                        loading={trophies.loading}
                                        onSaved={(trophy) => trophies.applyLocal(trophy.id, trophy)}
                                        onWithdrawn={(id) => trophies.applyLocal(id, null)}
                                    />
                                </TrophyGallery>

                                {/* Trophy Info (if separate from notes) */}
                                {film.movieClubInfo.trophyInfo &&
                                    !film.movieClubInfo.trophyNotes && (
                                        <div className="mt-8 pt-6 border-t border-slate-700">
                                            <h3 className="mb-1.5 text-[11px] font-medium uppercase tracking-[0.2em] text-blue-300/80">
                                                Trophy Info
                                            </h3>
                                            <p className="text-slate-300 whitespace-pre-line">
                                                {film.movieClubInfo.trophyInfo}
                                            </p>
                                        </div>
                                    )}

                                {/* What the club says back about the screening, as
                                on its wall row: the same thread, read and written
                                in either place. Draws nothing for a visitor when
                                nobody has responded, border included. */}
                                <LogResponses
                                    threadId={clubThreadId(film.imdbID)}
                                    owner={null}
                                    title={film.title}
                                    className="mt-8 border-t border-slate-700 pt-6"
                                />

                                {/* Previous / Next film in the club's watch timeline */}
                                <WatchTimelineNav
                                    previousFilm={previousFilm}
                                    nextFilm={nextFilm}
                                    nextSelectorPlaceholder={nextSelectorPlaceholder}
                                    sincePreviousGap={sincePreviousGap}
                                    untilNextGap={untilNextGap}
                                />
                            </div>
                        </div>
                    )}
                </BaseCard>

                {selectorName && filmsBySameSelector.length > 0 && (
                    <div className="mb-12">
                        <FilmList
                            films={filmsBySameSelector}
                            title={`More Films Selected by ${capitalizeFirstLetter(selectorName)}`}
                        />
                    </div>
                )}
            </div>
        </PageLayout>
    );
};

export default FilmDetailPage;
